1	//! Owned rollback values for exactly the properties a commit will change.
2	//! Capture must run while the caller serializes KMS operations on this device.
3	use super::atomic::{MAX_OBJECTS, MAX_PROPERTIES, Request};
4	use smithay::{
5	    backend::drm::{DrmDevice, DrmDeviceFd},
6	    reexports::{
7	        drm::control::{self, Device as _, ResourceHandle, property::ValueType},
8	        rustix::ioctl::opcode,
9	    },
10	};
11	use std::{
12	    collections::{BTreeMap, BTreeSet},
13	    io,
14	    os::fd::{AsFd, AsRawFd},
15	};
16	
17	const MAX_BLOB_BYTES: usize = 1024 * 1024;
18	const MAX_TOTAL_BLOB_BYTES: usize = 4 * 1024 * 1024;
19	
20	pub(super) struct RestoreState {
21	    request: Request,
22	    fd: Option<DrmDeviceFd>,
23	    blobs: Vec<u32>,
24	    blob_bytes: usize,
25	    framebuffers: Vec<control::framebuffer::Handle>,
26	    restored: bool,
27	    cleanup_errors: u64,
28	}
29	impl RestoreState {
30	    pub fn capture(drm: &DrmDevice, changed: &Request) -> io::Result<Self> {
31	        let resources = drm.resource_handles()?;
32	        let planes = drm.plane_handles()?;
33	        let mut objects = BTreeMap::new();
34	        for &h in resources.connectors() {
35	            insert_object(&mut objects, h)?;
36	        }
37	        for &h in resources.crtcs() {
38	            insert_object(&mut objects, h)?;
39	        }
40	        for &h in &planes {
41	            insert_object(&mut objects, h)?;
42	        }
43	        let mut snapshot = Self {
44	            request: Request::new(),
45	            fd: Some(drm.device_fd().clone()),
46	            blobs: Vec::new(),
47	            blob_bytes: 0,
48	            framebuffers: Vec::new(),
49	            restored: false,
50	            cleanup_errors: 0,
51	        };
52	        let mut old_blobs = BTreeMap::new();
53	        let mut old_fbs = BTreeMap::new();
54	        let mut properties = BTreeMap::new();
55	        let mut count = 0;
56	        for (object, property, _) in changed.entries() {
57	            count += 1;
58	            if count > MAX_PROPERTIES {
59	                return Err(invalid("too many rollback properties"));
60	            }
61	            let kind = *objects
62	                .get(&object)
63	                .ok_or_else(|| invalid("unknown rollback object"))?;
64	            if let std::collections::btree_map::Entry::Vacant(entry) = properties.entry(object) {
65	                let values = match kind {
66	                    control::connector::Handle::FFI_TYPE => {
67	                        drm.get_properties(handle::<control::connector::Handle>(object)?)?
68	                    }
69	                    control::crtc::Handle::FFI_TYPE => {
70	                        drm.get_properties(handle::<control::crtc::Handle>(object)?)?
71	                    }
72	                    control::plane::Handle::FFI_TYPE => {
73	                        drm.get_properties(handle::<control::plane::Handle>(object)?)?
74	                    }
75	                    _ => return Err(invalid("unsupported rollback object")),
76	                };
77	                if values.as_props_and_values().0.len() > MAX_PROPERTIES {
78	                    return Err(invalid("too many object properties"));
79	                }
80	                let mut current = BTreeMap::new();
81	                for (id, value) in values {
82	                    if current.insert(u32::from(id), value).is_some() {
83	                        return Err(invalid("duplicate object property"));
84	                    }
85	                }
86	                entry.insert(current);
87	            }
88	            let value = *properties[&object]
89	                .get(&property)
90	                .ok_or_else(|| invalid("property missing on rollback object"))?;
91	            let info = drm.get_property(handle::<control::property::Handle>(property)?)?;
92	            if !info.mutable() {
93	                return Err(invalid("immutable rollback property"));
94	            }
95	            let name = info.name().to_bytes();
96	            if transient(name) || !supported(kind, name) {
97	                return Err(invalid("unsupported or transient rollback property"));
98	            }
99	            let value = match info.value_type() {
100	                ValueType::Blob if value != 0 => {
101	                    let original = u32::try_from(value).map_err(|_| invalid("invalid blob ID"))?;
102	                    if let Some(&id) = old_blobs.get(&original) {
103	                        id
104	                    } else {
105	                        let id = snapshot.clone_blob(original)?;
106	                        old_blobs.insert(original, id);
107	                        id
108	                    }
109	                }
110	                ValueType::Framebuffer if value != 0 => {
111	                    if name != b"FB_ID" || kind != control::plane::Handle::FFI_TYPE {
112	                        return Err(invalid("unsupported framebuffer property"));
113	                    }
114	                    let original =
115	                        u32::try_from(value).map_err(|_| invalid("invalid framebuffer ID"))?;
116	                    if let Some(&id) = old_fbs.get(&original) {
117	                        id
118	                    } else {
119	                        let id = snapshot.clone_framebuffer(original)?;
120	                        old_fbs.insert(original, id);
121	                        id
122	                    }
123	                }
124	                ValueType::Unknown
125	                | ValueType::Object
126	                | ValueType::Property
127	                | ValueType::Encoder => return Err(invalid("unsupported property type")),
128	                _ => value,
129	            };
130	            snapshot
131	                .request
132	                .add(object, property, value)
133	                .map_err(|_| invalid("rollback request capacity"))?;
134	        }
135	        if count == 0 {
136	            return Err(invalid("empty rollback request"));
137	        }
138	        Ok(snapshot)
139	    }
140	    pub fn request(&self) -> &Request {
141	        &self.request
142	    }
143	    /// Mark before issuing rollback: an ioctl error may still be ambiguous.
144	    /// This permanently prevents RMFB cleanup of possibly restored scanout.
145	    /// The owner must retain the full backend/seat lease on restoration error.
146	    pub fn mark_restored(&mut self) {
147	        self.restored = true;
148	    }
149	    /// After synchronous rollback succeeds, release clone ownership without
150	    /// disabling restored planes. Failures retain FB IDs and the fd for retry;
151	    /// the caller must retain this entire state and its backend/seat owner.
152	    pub fn finish_restored(&mut self) -> io::Result<()> {
153	        if !self.restored {
154	            return Err(invalid("rollback not marked restored"));
155	        }
156	        let before = self.cleanup_errors;
157	        self.cleanup();
158	        if !self.framebuffers.is_empty() || !self.blobs.is_empty() || self.cleanup_errors != before
159	        {
160	            return Err(io::Error::other("rollback resource cleanup failed"));
161	        }
162	        Ok(())
163	    }
164	    pub fn cleanup_errors(&self) -> u64 {
165	        self.cleanup_errors
166	    }
167	    fn fd(&self) -> &DrmDeviceFd {
168	        self.fd.as_ref().expect("snapshot owns its DRM fd")
169	    }
170	    fn clone_blob(&mut self, original: u32) -> io::Result<u64> {
171	        let mut get = drm_sys::drm_mode_get_blob {
172	            blob_id: original,
173	            ..Default::default()
174	        };
175	        ioctl(self.fd(), 0xac, &mut get)?;
176	        let length = get.length as usize;
177	        if length == 0
178	            || length > MAX_BLOB_BYTES
179	            || self.blob_bytes.saturating_add(length) > MAX_TOTAL_BLOB_BYTES
180	        {
181	            return Err(invalid("rollback blob size limit"));
182	        }
183	        let mut bytes = vec![0u8; length];
184	        get.data = bytes.as_mut_ptr() as u64;
185	        ioctl(self.fd(), 0xac, &mut get)?;
186	        if get.length as usize != length {
187	            return Err(invalid("rollback blob changed size"));
188	        }
189	        let mut create = drm_sys::drm_mode_create_blob {
190	            data: bytes.as_ptr() as u64,
