285	            let request = match owned.target.flip_request() {
286	                Ok(r) => r,
287	                Err(e) => {
288	                    return SubmitOutcome::Rejected(PreviewFailure {
289	                        stage: PreviewStage::Prepare,
290	                        errno: e.errno,
291	                    });
292	                }
293	            };
294	            match request.submit(ctx.drm.as_fd(), cookie) {
295	                Ok(()) => SubmitOutcome::Accepted,
296	                Err(e) => SubmitOutcome::Uncertain(PreviewFailure::io(PreviewStage::Submit, e)),
297	            }
298	        });
