300	            Ok(_) => Ok(()),
301	            Err(SubmitError::Uncertain(e)) | Err(SubmitError::Rejected { error: e, .. }) => {
302	                s.last_failure = Some(e);
303	                Err(e)
304	            }
305	            Err(_) => Err(PreviewFailure::at(PreviewStage::Admission)),
306	        }
307	    }
308	    pub fn restore(&mut self) -> Result<(), PreviewFailure> {
309	        let s = self.state.as_mut().expect("live output owned");
310	        s.queue.invalidate();
311	        let rollback = &mut s.rollback;
312	        restore_consumers(&mut s.queue, s.key, &mut s.rollback_completed, || {
313	            rollback.mark_restored();
314	            rollback.request().apply_blocking(s.fd.as_fd())
315	        })?;
316	        s.rollback
317	            .finish_restored()
318	            .map_err(|e| PreviewFailure::io(PreviewStage::Cleanup, e))?;
319	        s.armed = false;
320	        Ok(())
321	    }
322	}
323	impl Drop for Output {
324	    fn drop(&mut self) {
325	        if let Some(state) = self.state.take()
326	            && state.armed
327	        {
328	            // No restore against a potentially revoked/replaced topology. Keep
329	            // resources, rollback clones, quota permits AND the broker lease.
330	            std::mem::forget(state);
331	        }
332	    }
333	}
334	
335	fn restore_consumers<R, S>(
336	    queue: &mut FrameQueue<R, S>,
337	    key: OutputKey,
338	    completed: &mut bool,
339	    restore: impl FnOnce() -> io::Result<()>,
340	) -> Result<(), PreviewFailure> {
341	    queue.invalidate();
342	    if !*completed {
343	        restore().map_err(|e| PreviewFailure::io(PreviewStage::Restore, e))?;
344	        // SAFETY: the platform closure succeeded only after a synchronous
345	        // atomic rollback replaced every plane consuming this queue's buffers.
346	        let proof = unsafe { IdleProof::after_backend_quiescence(key) };
347	        queue
348	            .release_after_disable(proof)
349	            .map_err(|_| PreviewFailure::at(PreviewStage::Restore))?;
350	        *completed = true;
351	    }
352	    Ok(())
353	}
354	#[cfg(test)]
