356	    use super::*;
357	    #[test]
358	    fn failed_restore_retains_front_and_pending_until_synchronous_success() {
359	        let ticket = Ticket {
360	            device: 1,
361	            generation: 1,
362	            session_epoch: 1,
363	        };
364	        let key = OutputKey::new(ticket, 7, 1).unwrap();
365	        let pool = FramePool::default();
366	        let mut queue = pool.output(key).unwrap();
367	        let frame = pool.prepare(4, || Ok::<_, ()>((1, ()))).unwrap();
368	        let cookie = queue
369	            .submit(frame, |_, _| SubmitOutcome::<()>::Accepted)
370	            .ok()
371	            .unwrap();
372	        queue.complete(
373	            ticket,
374	            crate::drm_events::Flip {
375	                cookie: cookie.get(),
376	                crtc: 7,
377	                sequence: 1,
378	                seconds: 0,
379	                microseconds: 0,
380	            },
381	        );
382	        let next = pool.prepare(4, || Ok::<_, ()>((2, ()))).unwrap();
383	        assert!(
384	            queue
385	                .submit(next, |_, _| SubmitOutcome::<()>::Accepted)
386	                .is_ok()
387	        );
388	        let mut completed = false;
389	        assert!(
390	            restore_consumers(&mut queue, key, &mut completed, || Err(
391	                io::Error::from_raw_os_error(libc::EBUSY)
392	            ))
393	            .is_err()
394	        );
395	        assert_eq!(pool.snapshot().slots, 2);
396	        assert!(!completed);
397	        assert!(queue.visible_scene().is_none());
398	        restore_consumers(&mut queue, key, &mut completed, || {
399	            assert_eq!(pool.snapshot().slots, 2);
400	            Ok(())
401	        })
402	        .unwrap();
403	        assert_eq!(pool.snapshot().slots, 0);
404	        assert!(queue.snapshot().closed && completed);
405	        restore_consumers(&mut queue, key, &mut completed, || {
406	            panic!("rollback must not repeat after clone IDs close")
407	        })
408	        .unwrap();
409	    }
410	}
